args.streamContent:
import { cacheTag, updateTag } from "next/cache";
import { getAllProducts } from "@/lib/db";

async function ProductListing() {
  "use cache";
  cacheTag("products");

  const products = await getAllProducts();

  return (
    <ul className="space-y-4">
      {products.map((product) => (
        <li
          key={product.id}
          className="rounded-lg border border-gray-200 p-4 shadow-sm"
        >
          <h3 className="font-semibold">{product.name}</h3>
          <p className="text-sm text-gray-600">{product.description}</p>
          <p className="mt-2 font-medium">
            ${(product.price / 100).toFixed(2)}
          </p>
        </li>
      ))}
    </ul>
  );
}

export default function Page() {
  async function invalidateProductsCache() {
    "use server";
    updateTag("products");
  }

  return (
    <div className="mx-auto max-w-2xl space-y-8 p-8">
      <h1 className="text-2xl font-bold">Product Listing</h1>

      <ProductListing />

      <form
        action={invalidateProductsCache}
        className="rounded-lg border border-dashed border-gray-300 p-4"
      >
        <p className="mb-3 text-sm text-gray-600">
          After adding or updating products in your database, click below to
          invalidate the cache and fetch fresh data.
        </p>
        <button
          type="submit"
          className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
        >
          Invalidate Products Cache
        </button>
      </form>
    </div>
  );
}

